 import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import { getCachedSettings } from '../services/settingsService'
import { initiatePayment } from '../services/paymentService'
import { Check, X, AlertCircle, Shield, CreditCard, FileText } from 'lucide-react'

export default function CreateCommunity() {
    const { user, profile } = useAuth()
    const { showToast } = useToast()
    const navigate = useNavigate()
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState('')
    const [checkingSettings, setCheckingSettings] = useState(true)
    const [showTermsModal, setShowTermsModal] = useState(false)
    const [acceptedTerms, setAcceptedTerms] = useState(false)
    const [submitting, setSubmitting] = useState(false)
    
    const settings = getCachedSettings()
    const defaultPrice = settings?.default_community_price || 50
    const communityCreationEnabled = settings?.community_creation_enabled !== false
    const maxCommunities = settings?.max_communities_per_user || 10
    const SETUP_FEE = 100

    const [form, setForm] = useState({
        name: '',
        description: '',
        is_private: true,
        price: defaultPrice,
        payment_type: 'monthly'
    })

    useEffect(() => {
        checkCommunityCreation()
        checkUserCommunityCount()
        setCheckingSettings(false)
    }, [])

    const checkCommunityCreation = async () => {
        if (!communityCreationEnabled) {
            setError('Community creation is currently disabled. Please try again later.')
            showToast('Community creation is disabled', 'error')
        }
    }

    const checkUserCommunityCount = async () => {
        if (!user) return

        try {
            const { count, error } = await supabase
                .from('communities')
                .select('*', { count: 'exact', head: true })
                .eq('creator_id', user.id)

            if (error) throw error

            if (count >= maxCommunities) {
                setError(`You have reached the maximum of ${maxCommunities} communities.`)
                showToast(`Maximum ${maxCommunities} communities reached`, 'warning')
            }
        } catch (error) {
            console.error('Error checking community count:', error)
        }
    }

    const handleOpenTerms = () => {
        setShowTermsModal(true)
    }

    const handleCloseTerms = () => {
        if (!acceptedTerms) {
            setShowTermsModal(false)
        }
    }

    const handleAcceptTerms = () => {
        setAcceptedTerms(true)
        setShowTermsModal(false)
        showToast('Terms accepted! You can now create your community.', 'success')
    }

    // ✅ Fixed: Proper payment form submission
    const submitPayFastForm = (payfastData, payfastUrl) => {
        const formElement = document.createElement('form')
        formElement.method = 'POST'
        formElement.action = payfastUrl
        
        Object.entries(payfastData).forEach(([key, value]) => {
            const input = document.createElement('input')
            input.type = 'hidden'
            input.name = key
            input.value = value
            formElement.appendChild(input)
        })
        
        document.body.appendChild(formElement)
        formElement.submit()
    }

    const handleSubmit = async (e) => {
        e.preventDefault()
        setError('')
        setSubmitting(true)

        if (!communityCreationEnabled) {
            setError('Community creation is currently disabled.')
            showToast('Community creation is disabled', 'error')
            setSubmitting(false)
            return
        }

        if (!form.name.trim()) {
            setError('Community name is required')
            setSubmitting(false)
            return
        }

        if (form.price < 0) {
            setError('Price cannot be negative')
            setSubmitting(false)
            return
        }

        if (!acceptedTerms) {
            setError('You must accept the Terms & Conditions to create a community')
            showToast('Please accept the Terms & Conditions first', 'warning')
            setSubmitting(false)
            return
        }

        try {
            // Check if user has a profile
            const { data: profileData, error: profileError } = await supabase
                .from('profiles')
                .select('id')
                .eq('id', user.id)
                .single()

            if (profileError || !profileData) {
                await supabase
                    .from('profiles')
                    .insert({
                        id: user.id,
                        username: user.email?.split('@')[0] || 'user',
                        full_name: user.email?.split('@')[0] || 'user'
                    })
            }

            // Step 1: Create the community with setup_fee_paid = FALSE
            const { data: community, error: communityError } = await supabase
                .from('communities')
                .insert({
                    creator_id: user.id,
                    name: form.name.trim(),
                    description: form.description.trim() || null,
                    is_private: form.is_private,
                    price: form.price,
                    payment_type: form.payment_type,
                    setup_fee_paid: false,
                    setup_fee_amount: SETUP_FEE
                })
                .select()
                .single()

            if (communityError) throw communityError

            // Step 2: Initiate payment for R100 setup fee
            const paymentResult = await initiatePayment(
                community.id,
                user.id,
                SETUP_FEE,
                `Community Setup Fee: ${form.name}`
            )

            if (!paymentResult.success) {
                // Delete the community if payment fails
                await supabase.from('communities').delete().eq('id', community.id)
                throw new Error(paymentResult.error || 'Payment failed')
            }

            // Step 3: Redirect to PayFast using the helper function
            submitPayFastForm(paymentResult.payfastData, paymentResult.payfastUrl)

        } catch (error) {
            console.error('Error creating community:', error)
            setError(error.message || 'Failed to create community')
            showToast('Failed to create community: ' + error.message, 'error')
            setSubmitting(false)
        }
    }

    // Check if community creation is enabled
    if (checkingSettings) {
        return (
            <div className="max-w-2xl mx-auto text-center py-12">
                <div className="text-gray-500">Loading...</div>
            </div>
        )
    }

    if (!communityCreationEnabled) {
        return (
            <div className="max-w-2xl mx-auto">
                <div className="bg-white rounded-xl shadow-md p-8 text-center">
                    <div className="text-4xl mb-4">🚫</div>
                    <h1 className="text-2xl font-bold text-gray-800 mb-2">Community Creation Disabled</h1>
                    <p className="text-gray-500">Community creation is currently disabled. Please check back later.</p>
                    <button
                        onClick={() => navigate('/community')}
                        className="mt-4 bg-gray-800 text-white px-4 py-2 rounded-lg hover:bg-gray-900 transition"
                    >
                        Back to Communities
                    </button>
                </div>
            </div>
        )
    }

    return (
        <div className="max-w-2xl mx-auto">
            <div className="bg-white rounded-xl shadow-md p-6 md:p-8">
                <h1 className="text-2xl font-bold text-gray-800 mb-2">Create Community</h1>
                <p className="text-gray-500 mb-6">
                    Create your own community and earn 70% of subscription fees
                </p>

                {/* Setup Fee Notice */}
                <div className="bg-blue-50 rounded-lg p-4 mb-6 border border-blue-200">
                    <div className="flex items-start gap-3">
                        <CreditCard size={20} className="text-blue-600 mt-0.5" />
                        <div>
                            <p className="text-sm font-medium text-blue-700">One-time Setup Fee: R{SETUP_FEE}</p>
                            <p className="text-sm text-blue-600">
                                You'll be redirected to PayFast to pay the setup fee before your community goes live.
                            </p>
                        </div>
                    </div>
                </div>

                {error && (
                    <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-4">
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-gray-700 font-medium mb-2">Community Name *</label>
                        <input
                            type="text"
                            value={form.name}
                            onChange={(e) => setForm({...form, name: e.target.value})}
                            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                            placeholder="Premier League Predictors"
                            required
                            maxLength="50"
                        />
                        <p className="text-xs text-gray-400 mt-1">{form.name.length}/50 characters</p>
                    </div>

                    <div className="mb-4">
                        <label className="block text-gray-700 font-medium mb-2">Description</label>
                        <textarea
                            value={form.description}
                            onChange={(e) => setForm({...form, description: e.target.value})}
                            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                            placeholder="A community for serious football predictors..."
                            rows="4"
                            maxLength="500"
                        />
                        <p className="text-xs text-gray-400 mt-1">{form.description.length}/500 characters</p>
                    </div>

                    <div className="mb-4">
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={form.is_private}
                                onChange={(e) => setForm({...form, is_private: e.target.checked})}
                                className="w-5 h-5 accent-green-600"
                            />
                            <div>
                                <span className="font-medium text-gray-700">Private Community</span>
                                <p className="text-sm text-gray-500">Only paying members can see posts in this community</p>
                            </div>
                        </label>
                    </div>

                    <div className="mb-4">
                        <label className="block text-gray-700 font-medium mb-2">Subscription Type</label>
                        <div className="grid grid-cols-2 gap-3">
                            <button
                                type="button"
                                onClick={() => setForm({...form, payment_type: 'monthly'})}
                                className={`px-4 py-3 rounded-lg border-2 text-sm font-medium transition ${
                                    form.payment_type === 'monthly'
                                        ? 'border-green-600 bg-green-50 text-green-600'
                                        : 'border-gray-300 bg-white text-gray-700 hover:border-gray-400'
                                }`}
                            >
                                Monthly
                            </button>
                            <button
                                type="button"
                                onClick={() => setForm({...form, payment_type: 'one_time'})}
                                className={`px-4 py-3 rounded-lg border-2 text-sm font-medium transition ${
                                    form.payment_type === 'one_time'
                                        ? 'border-green-600 bg-green-50 text-green-600'
                                        : 'border-gray-300 bg-white text-gray-700 hover:border-gray-400'
                                }`}
                            >
                                One-time
                            </button>
                        </div>
                    </div>

                    <div className="mb-6">
                        <label className="block text-gray-700 font-medium mb-2">Price (ZAR) per {form.payment_type === 'monthly' ? 'month' : 'payment'}</label>
                        <div className="flex items-center gap-2">
                            <span className="text-lg font-bold text-gray-600">R</span>
                            <input
                                type="number"
                                min="0"
                                step="5"
                                value={form.price}
                                onChange={(e) => setForm({...form, price: parseFloat(e.target.value) || 0})}
                                className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                            />
                        </div>
                        <p className="text-xs text-gray-400 mt-1">
                            You earn 70% of this amount (R{(form.price * 0.7).toFixed(2)}) per {form.payment_type === 'monthly' ? 'month' : 'payment'} after setup fee
                        </p>
                    </div>

                    {/* Terms & Conditions Acceptance */}
                    <div className="mb-6 p-4 bg-gray-50 rounded-lg border border-gray-200">
                        <div className="flex items-start gap-3">
                            <input
                                type="checkbox"
                                checked={acceptedTerms}
                                onChange={(e) => {
                                    if (!acceptedTerms) {
                                        handleOpenTerms()
                                    } else {
                                        setAcceptedTerms(false)
                                    }
                                }}
                                className="w-5 h-5 accent-green-600 mt-0.5"
                            />
                            <div>
                                <span className="text-sm text-gray-700">
                                    I have read and agree to the{' '}
                                    <button
                                        type="button"
                                        onClick={handleOpenTerms}
                                        className="text-green-600 hover:text-green-700 font-semibold underline"
                                    >
                                        Community Terms & Conditions
                                    </button>
                                </span>
                                <p className="text-xs text-gray-400 mt-1">
                                    You must accept the terms before creating a community
                                </p>
                            </div>
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={submitting || !acceptedTerms}
                        className="w-full bg-green-600 text-white py-3 rounded-lg font-semibold hover:bg-green-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {submitting ? 'Processing...' : `Create Community - Pay R${SETUP_FEE} Setup Fee`}
                    </button>
                </form>
            </div>

            {/* Terms & Conditions Modal */}
            {showTermsModal && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-center">
                            <div className="flex items-center gap-2">
                                <FileText size={24} className="text-green-600" />
                                <h2 className="text-xl font-bold text-gray-800">Community Terms & Conditions</h2>
                            </div>
                            <button
                                onClick={() => setShowTermsModal(false)}
                                className="text-gray-400 hover:text-gray-600"
                            >
                                <X size={24} />
                            </button>
                        </div>

                        <div className="p-6 space-y-4">
                            <div className="bg-blue-50 rounded-lg p-4 border border-blue-200">
                                <div className="flex items-start gap-3">
                                    <Shield size={20} className="text-blue-600 mt-0.5" />
                                    <div>
                                        <p className="font-medium text-blue-700">Fee Structure</p>
                                        <ul className="text-sm text-blue-600 mt-2 space-y-1">
                                            <li>• <strong>Setup Fee:</strong> R100 (one-time)</li>
                                            <li>• <strong>Platform Fee:</strong> 25% of each subscription</li>
                                            <li>• <strong>Payment Gateway Fee:</strong> 5% of each subscription</li>
                                            <li>• <strong>Total Fee:</strong> 30% of each subscription</li>
                                            <li>• <strong>You Earn:</strong> 70% of each subscription</li>
                                        </ul>
                                    </div>
                                </div>
                            </div>

                            <div className="bg-yellow-50 rounded-lg p-4 border border-yellow-200">
                                <div className="flex items-start gap-3">
                                    <AlertCircle size={20} className="text-yellow-600 mt-0.5" />
                                    <div>
                                        <p className="font-medium text-yellow-700">Important Information</p>
                                        <ul className="text-sm text-yellow-600 mt-2 space-y-1">
                                            <li>• You must be 18 years or older to create a community</li>
                                            <li>• You are responsible for all content posted in your community</li>
                                            <li>• You agree to moderate your community and enforce community guidelines</li>
                                            <li>• You agree to pay the R100 setup fee (non-refundable)</li>
                                            <li>• Payouts are processed monthly via PayFast</li>
                                        </ul>
                                    </div>
                                </div>
                            </div>

                            <div className="space-y-2 text-sm text-gray-600">
                                <h3 className="font-semibold text-gray-800">1. Community Guidelines</h3>
                                <p>You agree to maintain a safe and respectful environment. Hate speech, harassment, or illegal content is strictly prohibited.</p>

                                <h3 className="font-semibold text-gray-800 mt-4">2. Payment Terms</h3>
                                <p>The R100 setup fee is non-refundable. Subscription fees are collected and distributed monthly.</p>

                                <h3 className="font-semibold text-gray-800 mt-4">3. Payout Schedule</h3>
                                <p>Earnings are paid out monthly via PayFast. Payouts are processed on the 15th of each month.</p>

                                <h3 className="font-semibold text-gray-800 mt-4">4. Termination</h3>
                                <p>We reserve the right to terminate communities that violate our terms or are inactive for 90+ days.</p>

                                <h3 className="font-semibold text-gray-800 mt-4">5. Liability</h3>
                                <p>You are solely responsible for the content and activity within your community.</p>
                            </div>

                            <div className="border-t border-gray-200 pt-4 flex gap-3">
                                <button
                                    onClick={handleAcceptTerms}
                                    className="flex-1 bg-green-600 text-white py-2.5 rounded-lg font-semibold hover:bg-green-700 transition flex items-center justify-center gap-2"
                                >
                                    <Check size={18} /> I Accept the Terms
                                </button>
                                <button
                                    onClick={() => setShowTermsModal(false)}
                                    className="flex-1 bg-gray-200 text-gray-700 py-2.5 rounded-lg font-semibold hover:bg-gray-300 transition"
                                >
                                    Cancel
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
